int main(int argc,char** argv){try{if(!has_project() || !has_tiff() || !has_geos() || !has_linear_unmixing()){std::cout<<"Optional native project/TIFF/GEOS/unmixing unavailable\n";return 0;}const auto root=argc>1?fs::u8path(argv[1]):fs::current_path()/("linear-unmix-gui-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(root);check(glfwInit(),"GLFW init");glfwWindowHint(GLFW_VISIBLE,GLFW_FALSE);glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR,3);glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR,3);auto* window=glfwCreateWindow(1280,1100,"Native linear unmixing workflow",nullptr,nullptr);check(window,"GLFW window");glfwMakeContextCurrent(window);ImGui::CreateContext();ImGui::GetIO().IniFilename=nullptr;ImGui::GetIO().ConfigInputTrickleEventQueue=false;ImGui::GetIO().Fonts->AddFontDefault();ImGui_ImplGlfw_InitForOpenGL(window,true);ImGui_ImplOpenGL3_Init("#version 330");exercise(root,window,argc>2 && std::string(argv[2])=="--handoff");ImGui_ImplOpenGL3_Shutdown();ImGui_ImplGlfw_Shutdown();ImGui::DestroyContext();glfwDestroyWindow(window);glfwTerminate();}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
